import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { Chess } from "chess.js";
import { ENCODING_VERSION, MOVES, NUM_MOVES, decodeMove, encodeBoard, encodeMove, legalMoves } from "./encode";

// Generated by training/make_test_vectors.py from the Python encoder.
type Vector = { fen: string; planes: string; legal: Record<string, number> };
const vectors: { encoding_version: number; moves: string[]; positions: Vector[] } = JSON.parse(
  readFileSync(new URL("../../../shared/encoding_vectors.json", import.meta.url), "utf8"),
);

/** The Python side's hex string of bit-packed planes -> 0/1 array. */
function unpackHex(hex: string): number[] {
  const bits: number[] = [];
  for (let i = 0; i < hex.length; i += 2) {
    const byte = parseInt(hex.slice(i, i + 2), 16);
    for (let bit = 7; bit >= 0; bit--) bits.push((byte >> bit) & 1);
  }
  return bits;
}

const uci = (m: { from: string; to: string; promotion?: string }) => m.from + m.to + (m.promotion ?? "");

describe("encoding parity with Python", () => {
  it("uses the same encoding version", () => {
    expect(ENCODING_VERSION).toBe(vectors.encoding_version);
  });

  it("builds the identical 1858-move table", () => {
    expect(MOVES.length).toBe(NUM_MOVES);
    expect([...MOVES]).toEqual(vectors.moves);
  });

  it(`encodes all ${vectors.positions.length} reference positions identically`, () => {
    for (const { fen, planes } of vectors.positions) {
      const ours = Array.from(encodeBoard(new Chess(fen)));
      expect(ours, fen).toEqual(unpackHex(planes));
    }
  });

  it("gives every legal move the same policy index", () => {
    for (const { fen, legal } of vectors.positions) {
      const game = new Chess(fen);
      const ours = Object.fromEntries(legalMoves(game).map(({ index, move }) => [uci(move), index]));
      expect(ours, fen).toEqual(legal);
    }
  });

  it("decodes every index back to the same move", () => {
    for (const { fen, legal } of vectors.positions) {
      const game = new Chess(fen);
      for (const [move, index] of Object.entries(legal)) {
        expect(uci(decodeMove(index, game)), `${fen} ${move}`).toBe(move);
      }
    }
  });
});

describe("encodeBoard batching", () => {
  it("writes at an offset without touching the rest of the buffer", () => {
    const size = 18 * 64;
    const buffer = new Float32Array(size * 2).fill(7);
    encodeBoard(new Chess(), buffer, size);
    expect(buffer.slice(0, size).every((v) => v === 7)).toBe(true);
    expect(Array.from(buffer.slice(size))).toEqual(Array.from(encodeBoard(new Chess())));
  });
});

describe("encodeMove", () => {
  it("rejects moves with no policy slot", () => {
    expect(() => encodeMove({ from: "a1", to: "b4" }, "w")).toThrow();
  });
});
